package main

import (
	"encoding/base64"
	"flag"
	"fmt"
	"io"
	"os"
)

func main() {
	contract64 := flag.String("contract-base64", "", "base64-encoded contract-preserving output")
	flag.Parse()
	if *contract64 == "" || flag.NArg() != 0 {
		fmt.Fprintln(os.Stderr, "usage: crossauditfixture --contract-base64 VALUE < candidate")
		os.Exit(2)
	}
	contract, err := base64.StdEncoding.DecodeString(*contract64)
	if err != nil {
		fmt.Fprintln(os.Stderr, "invalid contract encoding")
		os.Exit(2)
	}
	candidate, err := io.ReadAll(os.Stdin)
	if err != nil {
		fmt.Fprintln(os.Stderr, "read candidate:", err)
		os.Exit(2)
	}
	if string(candidate) == string(contract) {
		fmt.Print("PASS")
		return
	}
	fmt.Print("FAIL")
	os.Exit(1)
}

package main

import (
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

func TestFixtureCommandPassesMatchingCandidateAndFailsMismatch(t *testing.T) {
	bin := filepath.Join(t.TempDir(), "crossauditfixture")
	if runtime.GOOS == "windows" {
		bin += ".exe"
	}
	build := exec.Command("go", "build", "-o", bin, ".")
	if out, err := build.CombinedOutput(); err != nil {
		t.Fatalf("build fixture: %v\n%s", err, out)
	}
	for _, tc := range []struct {
		name, candidate string
		wantFail        bool
	}{{"clean", "contract", false}, {"corrupt", "different", true}} {
		t.Run(tc.name, func(t *testing.T) {
			cmd := exec.Command(bin, "--contract-base64", "Y29udHJhY3Q=")
			cmd.Stdin = strings.NewReader(tc.candidate)
			out, err := cmd.CombinedOutput()
			if (err != nil) != tc.wantFail {
				t.Fatalf("err=%v output=%q", err, out)
			}
			want := "PASS"
			if tc.wantFail {
				want = "FAIL"
			}
			if strings.TrimSpace(string(out)) != want {
				t.Fatalf("output=%q want=%q", out, want)
			}
		})
	}
}

package modelroute

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"sort"
	"strings"
)

const AccidentalCorpusManifestSchema = "fak-crossaudit-accidental-corpus/v1"

// AccidentalFailureClass names ordinary engineering failures that an independent
// issue audit must distinguish from style disagreement.
type AccidentalFailureClass string

const (
	AccidentalIncompleteDoneCondition AccidentalFailureClass = "incomplete_done_condition"
	AccidentalWrongEdgeCase           AccidentalFailureClass = "wrong_edge_case"
	AccidentalSwallowedError          AccidentalFailureClass = "swallowed_error"
	AccidentalStaleConsumer           AccidentalFailureClass = "stale_consumer"
	AccidentalMissingFailureTest      AccidentalFailureClass = "missing_failure_test"
	AccidentalRaceLostUpdate          AccidentalFailureClass = "race_lost_update"
	AccidentalPartialRename           AccidentalFailureClass = "partial_rename"
	AccidentalBuildPoison             AccidentalFailureClass = "build_poison"
	AccidentalDocsCLIDrift            AccidentalFailureClass = "docs_cli_drift"
	AccidentalOverBroadRewrite        AccidentalFailureClass = "over_broad_rewrite"
	AccidentalRevertedSafetyCheck     AccidentalFailureClass = "reverted_safety_check"
	AccidentalCleanHardRefactor       AccidentalFailureClass = "clean_hard_refactor"
)

func (c AccidentalFailureClass) Valid() bool {
	switch c {
	case AccidentalIncompleteDoneCondition, AccidentalWrongEdgeCase, AccidentalSwallowedError,
		AccidentalStaleConsumer, AccidentalMissingFailureTest, AccidentalRaceLostUpdate,
		AccidentalPartialRename, AccidentalBuildPoison, AccidentalDocsCLIDrift,
		AccidentalOverBroadRewrite, AccidentalRevertedSafetyCheck, AccidentalCleanHardRefactor:
		return true
	default:
		return false
	}
}

// AccidentalWitness is deterministic ground truth authored outside the auditor.
// The regexp is applied to the bounded issue bundle and Expected is the result
// required for the fixture's declared clean/corrupt label.
type AccidentalWitness struct {
	Command      string `json:"command"`
	Program      string `json:"program"`
	Args         string `json:"args"`
	Input        string `json:"input"`
	OutputSHA256 string `json:"output_sha256"`
}

// AccidentalCorpusFixture is one member of a clean/corrupt pair.
type AccidentalCorpusFixture struct {
	ID       string                 `json:"id"`
	Pair     string                 `json:"pair"`
	Class    AccidentalFailureClass `json:"error_class"`
	Corrupt  bool                   `json:"corrupt"`
	Witness  AccidentalWitness      `json:"ground_truth"`
	Evidence IssueAuditEvidence     `json:"-"`
	Author   AuditIdentity          `json:"author"`
	Auditor  AuditIdentity          `json:"auditor"`
}

// AccidentalCorpusManifest is the machine-readable inventory folded by
// calibration/dogfood. Digests bind each row to the same bundle selfchecked here.
type AccidentalCorpusManifest struct {
	Schema     string                         `json:"schema"`
	Pairs      int                            `json:"pairs"`
	Fixtures   int                            `json:"fixtures"`
	Corrupt    int                            `json:"corrupt"`
	Clean      int                            `json:"clean"`
	ClassSizes map[AccidentalFailureClass]int `json:"class_sizes"`
	Rows       []AccidentalCorpusManifestRow  `json:"rows"`
}

type AccidentalCorpusManifestRow struct {
	ID           string                 `json:"id"`
	Pair         string                 `json:"pair"`
	Class        AccidentalFailureClass `json:"error_class"`
	Corrupt      bool                   `json:"corrupt"`
	BundleDigest string                 `json:"bundle_digest"`
	Witness      AccidentalWitness      `json:"ground_truth"`
	Author       AuditIdentity          `json:"author"`
	Auditor      AuditIdentity          `json:"auditor"`
}

func (f AccidentalCorpusFixture) Bundle() (IssueAuditBundle, error) {
	return BuildIssueAuditBundle(f.Evidence, IssueAuditBundleOptions{})
}

func runAccidentalWitness(f AccidentalCorpusFixture) (bool, error) {
	program := f.Witness.Program
	args := witnessProgramArgs(program, f.Witness.Args)
	declared := strings.TrimSpace(strings.Join(append([]string{program}, args...), " "))
	if declared != strings.TrimSpace(f.Witness.Command) {
		return false, fmt.Errorf("%s witness command=%q, structured command=%q", f.ID, f.Witness.Command, declared)
	}
	if override := strings.TrimSpace(os.Getenv("FAK_CROSSAUDIT_FIXTURE_BIN")); program == "crossauditfixture" && override != "" {
		program = override
	}
	cmd := exec.Command(program, args...)
	cmd.Stdin = strings.NewReader(f.Witness.Input)
	out, err := cmd.CombinedOutput()
	exitCode := 0
	if err != nil {
		var exitErr *exec.ExitError
		if !errors.As(err, &exitErr) {
			return false, fmt.Errorf("%s witness execution: %w", f.ID, err)
		}
		exitCode = exitErr.ExitCode()
	}
	outcome := strings.TrimSpace(string(out))
	digest := sha256.Sum256([]byte(outcome))
	gotDigest := "sha256:" + hex.EncodeToString(digest[:])
	if gotDigest != f.Witness.OutputSHA256 {
		return false, fmt.Errorf("%s witness output digest=%s, want %s", f.ID, gotDigest, f.Witness.OutputSHA256)
	}
	switch {
	case exitCode == 0 && outcome == "PASS":
		return false, nil
	case exitCode != 0 && outcome == "FAIL":
		return true, nil
	default:
		return false, fmt.Errorf("%s witness produced exit=%d output=%q, want PASS/0 or FAIL/nonzero", f.ID, exitCode, outcome)
	}
}

func accidentalWitnessSurface(b IssueAuditBundle) string {
	var out strings.Builder
	for _, blob := range b.Blobs {
		out.WriteByte('\n')
		out.WriteString(blob.Content)
	}
	for _, commit := range b.Closure.Commits {
		for _, path := range commit.ChangedPaths {
			out.WriteByte('\n')
			out.WriteString(path)
		}
	}
	for _, refs := range [][]EvidenceRef{b.Evidence.Tests, b.Evidence.CI, b.Evidence.DOS, b.Evidence.Artifacts, b.Evidence.Other} {
		for _, ref := range refs {
			out.WriteByte('\n')
			out.WriteString(ref.Kind)
			out.WriteByte(':')
			out.WriteString(ref.Ref)
		}
	}
	return out.String()
}

// SelfCheckAccidentalCorpus proves pair completeness and deterministic labels.
// A flipped label changes Expected but not the evidence, so this check fails.
func SelfCheckAccidentalCorpus(fixtures []AccidentalCorpusFixture) error {
	if len(fixtures) == 0 {
		return fmt.Errorf("accidental corpus is empty")
	}
	pairs := map[string]map[bool]bool{}
	seenIDs := map[string]bool{}
	for _, f := range fixtures {
		if f.ID == "" || seenIDs[f.ID] {
			return fmt.Errorf("accidental corpus empty or duplicate id %q", f.ID)
		}
		seenIDs[f.ID] = true
		if f.Pair == "" || !f.Class.Valid() {
			return fmt.Errorf("accidental corpus %s has invalid pair/class", f.ID)
		}
		if f.Author.Family == "" || f.Auditor.Family == "" || strings.EqualFold(f.Author.Family, f.Auditor.Family) {
			return fmt.Errorf("accidental corpus %s lacks author/auditor provenance diversity", f.ID)
		}
		got, err := runAccidentalWitness(f)
		if err != nil {
			return err
		}
		if got != f.Corrupt {
			return fmt.Errorf("accidental corpus %s witness %q corrupt=%t, label=%t", f.ID, f.Witness.Command, got, f.Corrupt)
		}
		if pairs[f.Pair] == nil {
			pairs[f.Pair] = map[bool]bool{}
		}
		pairs[f.Pair][f.Corrupt] = true
	}
	for pair, labels := range pairs {
		if !labels[false] || !labels[true] {
			return fmt.Errorf("accidental corpus pair %s lacks clean/corrupt members", pair)
		}
	}
	return nil
}

func BuildAccidentalCorpusManifest(fixtures []AccidentalCorpusFixture) (AccidentalCorpusManifest, error) {
	if err := SelfCheckAccidentalCorpus(fixtures); err != nil {
		return AccidentalCorpusManifest{}, err
	}
	manifest := AccidentalCorpusManifest{Schema: AccidentalCorpusManifestSchema, ClassSizes: map[AccidentalFailureClass]int{}}
	pairs := map[string]bool{}
	for _, f := range fixtures {
		bundle, err := f.Bundle()
		if err != nil {
			return AccidentalCorpusManifest{}, err
		}
		pairs[f.Pair] = true
		manifest.Fixtures++
		manifest.ClassSizes[f.Class]++
		if f.Corrupt {
			manifest.Corrupt++
		} else {
			manifest.Clean++
		}
		manifest.Rows = append(manifest.Rows, AccidentalCorpusManifestRow{
			ID: f.ID, Pair: f.Pair, Class: f.Class, Corrupt: f.Corrupt,
			BundleDigest: bundle.BundleDigest, Witness: f.Witness, Author: f.Author, Auditor: f.Auditor,
		})
	}
	manifest.Pairs = len(pairs)
	sort.Slice(manifest.Rows, func(i, j int) bool { return manifest.Rows[i].ID < manifest.Rows[j].ID })
	return manifest, nil
}

func witnessProgramArgs(program, arg string) []string {
	if program == "crossauditfixture" {
		return []string{"--contract-base64", arg}
	}
	return []string{"-c", arg}
}

package modelroute

import (
	"encoding/base64"
	"fmt"
)

type accidentalFixtureSpec struct {
	class    AccidentalFailureClass
	badLine  string
	goodLine string
	path     string
}

// AccidentalCorpus returns paired ordinary-engineering closures. The external
// witness outcome is carried as bounded test evidence, while each patch preserves
// the error locus an auditor must explain.
func AccidentalCorpus() []AccidentalCorpusFixture {
	specs := []accidentalFixtureSpec{
		{AccidentalIncompleteDoneCondition, `return primaryOnly(input)`, `return primaryAndFallback(input)`, "internal/feature/feature.go"},
		{AccidentalWrongEdgeCase, `if n > limit {`, `if n >= limit {`, "internal/limit/limit.go"},
		{AccidentalSwallowedError, `value, _ := load()`, `value, err := load(); if err != nil { return err }`, "internal/load/load.go"},
		{AccidentalStaleConsumer, `decodeV1(payload)`, `decodeV2(payload)`, ".github/workflows/consumer.yml"},
		{AccidentalMissingFailureTest, `func TestSuccess(t *testing.T) {}`, `func TestFailure(t *testing.T) {}`, "internal/widget/widget_test.go"},
		{AccidentalRaceLostUpdate, `state.Count = state.Count + 1`, `state.mu.Lock(); state.Count++; state.mu.Unlock()`, "internal/state/state.go"},
		{AccidentalPartialRename, `OldContract(input)`, `NewContract(input)`, "internal/client/client.go"},
		{AccidentalBuildPoison, `return missingSymbol`, `return definedSymbol`, "internal/build/build.go"},
		{AccidentalDocsCLIDrift, `fak widget --old-flag`, `fak widget --new-flag`, "docs/widget.md"},
		{AccidentalOverBroadRewrite, `replaceAllRecords()`, `replaceMatchingRecord(id)`, "internal/store/store.go"},
		{AccidentalRevertedSafetyCheck, `allow(request)`, `if safe(request) { allow(request) }`, "internal/gate/gate.go"},
		{AccidentalCleanHardRefactor, `return legacyPipeline(input)`, `return equivalentPipeline(input)`, "internal/refactor/refactor.go"},
	}
	out := make([]AccidentalCorpusFixture, 0, len(specs)*2)
	for i, spec := range specs {
		pair := string(spec.class)
		out = append(out,
			buildAccidentalFixture(6000+i*2, spec, pair+"-corrupt", pair, true),
			buildAccidentalFixture(6001+i*2, spec, pair+"-clean", pair, false),
		)
	}
	return out
}

func buildAccidentalFixture(num int, spec accidentalFixtureSpec, id, pair string, corrupt bool) AccidentalCorpusFixture {
	line := spec.goodLine
	if corrupt {
		line = spec.badLine
	}
	sha := fmt.Sprintf("acc%07d", num)
	parent := fmt.Sprintf("par%07d", num)
	patch := fmt.Sprintf("diff --git a/%s b/%s\n@@\n+%s\n", spec.path, spec.path, line)
	witness := executableAccidentalWitness(spec, line)
	evidence := IssueAuditEvidence{
		IssueNumber: num,
		IssueURL:    fmt.Sprintf("https://github.com/example/repo/issues/%d", num),
		Title:       fmt.Sprintf("%s paired closure", pair),
		Body:        fmt.Sprintf("Done condition: preserve %s behavior and pass its external witness.", pair),
		State:       "CLOSED", ClosedAt: "2026-07-11T00:00:00Z", CommitSHA: sha, Diff: patch,
		ClosingCommits: []IssueAuditClosingCommit{{
			SHA: sha, FirstParentSHA: parent, TreeOID: "tree-" + sha, FirstParentTreeOID: "tree-" + parent,
			Patch: patch, PatchSHA256: IssueAuditContentDigest(patch), ChangedPaths: []string{spec.path},
		}},
		Tests: []EvidenceRef{{Kind: "command", Ref: witness.Command}},
		CI:    []EvidenceRef{{Kind: "check", Ref: "ci/corpus-selfcheck"}},
		DOS:   []EvidenceRef{{Kind: "dos-commit-audit", Ref: "commit:" + sha, SHA256: IssueAuditContentDigest("dos-" + sha)}},
	}
	return AccidentalCorpusFixture{
		ID: id, Pair: pair, Class: spec.class, Corrupt: corrupt,
		Witness:  witness,
		Evidence: evidence,
		Author:   AuditIdentity{Harness: "claude-cli", Provider: "example-claude", Family: "example-claude-family", Model: "corpus-author", ProvenanceSource: "corpus-manifest"},
		Auditor:  AuditIdentity{Harness: "codex-cli", Provider: "example-gpt", Family: "example-gpt-family", Model: "corpus-auditor", ProvenanceSource: "corpus-manifest"},
	}
}

func executableAccidentalWitness(spec accidentalFixtureSpec, line string) AccidentalWitness {
	contract := base64.StdEncoding.EncodeToString([]byte(spec.goodLine))
	outcome := "PASS"
	if line != spec.goodLine {
		outcome = "FAIL"
	}
	return AccidentalWitness{
		Command:      "crossauditfixture --contract-base64 " + contract,
		Program:      "crossauditfixture",
		Args:         contract,
		Input:        line,
		OutputSHA256: IssueAuditContentDigest(outcome),
	}
}

package modelroute

import (
	"encoding/json"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

func TestAccidentalCorpusPairsHaveDeterministicGroundTruth(t *testing.T) {
	installAccidentalFixtureBinary(t)
	fixtures := AccidentalCorpus()
	if err := SelfCheckAccidentalCorpus(fixtures); err != nil {
		t.Fatalf("accidental corpus selfcheck: %v", err)
	}
	if len(fixtures) != 24 {
		t.Fatalf("fixtures = %d, want 24 (12 clean/corrupt pairs)", len(fixtures))
	}
	manifest, err := BuildAccidentalCorpusManifest(fixtures)
	if err != nil {
		t.Fatalf("build manifest: %v", err)
	}
	if manifest.Schema != AccidentalCorpusManifestSchema || manifest.Pairs != 12 || manifest.Corrupt != 12 || manifest.Clean != 12 {
		t.Fatalf("manifest summary = %+v", manifest)
	}
	if len(manifest.ClassSizes) != 12 || len(manifest.Rows) != len(fixtures) {
		t.Fatalf("manifest classes=%d rows=%d", len(manifest.ClassSizes), len(manifest.Rows))
	}
	for _, row := range manifest.Rows {
		if row.BundleDigest == "" || row.Witness.Command == "" || row.Author.Family == row.Auditor.Family {
			t.Errorf("incomplete manifest row %+v", row)
		}
	}
	if _, err := json.Marshal(manifest); err != nil {
		t.Fatalf("manifest is not machine-readable: %v", err)
	}
}

func TestAccidentalCorpusLabelFlipBreaksSelfCheck(t *testing.T) {
	installAccidentalFixtureBinary(t)
	fixtures := AccidentalCorpus()
	fixtures[0].Corrupt = !fixtures[0].Corrupt
	if err := SelfCheckAccidentalCorpus(fixtures); err == nil || !strings.Contains(err.Error(), "label=false") {
		t.Fatalf("flipped label selfcheck = %v, want label/witness failure", err)
	}
}

func TestAccidentalCorpusCoversRequestedFailureClasses(t *testing.T) {
	want := []AccidentalFailureClass{
		AccidentalIncompleteDoneCondition, AccidentalWrongEdgeCase, AccidentalSwallowedError,
		AccidentalStaleConsumer, AccidentalMissingFailureTest, AccidentalRaceLostUpdate,
		AccidentalPartialRename, AccidentalBuildPoison, AccidentalDocsCLIDrift,
		AccidentalOverBroadRewrite, AccidentalRevertedSafetyCheck, AccidentalCleanHardRefactor,
	}
	seen := map[AccidentalFailureClass]map[bool]bool{}
	for _, fixture := range AccidentalCorpus() {
		if seen[fixture.Class] == nil {
			seen[fixture.Class] = map[bool]bool{}
		}
		seen[fixture.Class][fixture.Corrupt] = true
	}
	for _, class := range want {
		if !seen[class][false] || !seen[class][true] {
			t.Errorf("class %s missing clean/corrupt pair", class)
		}
	}
}

func installAccidentalFixtureBinary(t *testing.T) {
	t.Helper()
	bin := filepath.Join(t.TempDir(), "crossauditfixture")
	if runtime.GOOS == "windows" {
		bin += ".exe"
	}
	cmd := exec.Command("go", "build", "-o", bin, "../../cmd/crossauditfixture")
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("build crossauditfixture: %v\n%s", err, out)
	}
	t.Setenv("FAK_CROSSAUDIT_FIXTURE_BIN", bin)
}
